import org.jsoup.Connection;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

import java.net.MalformedURLException;
import java.net.URL;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void urlBuilderConstructorValidUrlTest() {
        try {
            URL url = new URL("https://www.google.com");
            UrlBuilder urlBuilder = new UrlBuilder(url);
            Assert.assertNotNull(urlBuilder);
        } catch (MalformedURLException e) {
            Assert.fail();
        }
    }

    @Test(expected = NullPointerException.class)
    public void urlBuilderConstructorNullUrlTest() {
        UrlBuilder urlBuilder = new UrlBuilder(null);
    }

    @Test
    public void buildValidUrlTest() {
        try {
            URL initialUrl = new URL("https://www.google.com");
            UrlBuilder urlBuilder = new UrlBuilder(initialUrl);
            URL url = urlBuilder.build();
            Assert.assertEquals(initialUrl, url);
        } catch (MalformedURLException e) {
            Assert.fail();
        }
    }

    @Test
    public void appendKeyValValidValueTest() {
        try {
            URL initialUrl = new URL("https://www.google.com");
            UrlBuilder urlBuilder = new UrlBuilder(initialUrl);
            Connection.KeyVal keyVal = new Connection.KeyVal("key", "value");
            urlBuilder.appendKeyVal(keyVal);
            URL urlWithQuery = urlBuilder.build();
            Assert.assertEquals("https://www.google.com?key=value", urlWithQuery.toString());
        } catch (MalformedURLException | UnsupportedEncodingException e) {
            Assert.fail();
        }
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValInvalidEncodingTest() throws UnsupportedEncodingException {
        URL initialUrl;
        try {
            initialUrl = new URL("https://www.google.com");
            UrlBuilder urlBuilder = new UrlBuilder(initialUrl);
            Connection.KeyVal keyVal = Mockito.mock(Connection.KeyVal.class);
            Mockito.when(keyVal.key()).thenReturn("key░");  
            Mockito.when(keyVal.value()).thenReturn("value");
            urlBuilder.appendKeyVal(keyVal);
        } catch (MalformedURLException e) {
            Assert.fail();
        }
    }

    @Test(expected = NullPointerException.class)
    public void appendKeyValNullValueTest() throws UnsupportedEncodingException {
        URL initialUrl;
        try {
            initialUrl = new URL("https://www.google.com");
            UrlBuilder urlBuilder = new UrlBuilder(initialUrl);
            urlBuilder.appendKeyVal(null);
        } catch (MalformedURLException e) {
            Assert.fail();
        }
    }
}
